sys_script_include.script:
var NowflixUtils = Class.create();
NowflixUtils.prototype = {
    initialize: function() {},
    refQualMedia: function() {

        var mediasToBeShown = [];
        var grMedia = new GlideRecord("x_1960572_nowflix_media");
        grMedia.addQuery("state", "3");
        grMedia.query();

        while (grMedia.next()) {
            var grReview = new GlideRecord("x_1960572_nowflix_review");
            grReview.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4" + "^media.sys_id=" + grMedia.sys_id);
            //grReview.addQuery("opened_by", gs.getUserID());
            //grReview.addQuery("media", grMedia.sys_id);
            //grReview.addQuery("state", "!=", "4");

			grReview.query();

            if (!grReview.next()) {
                mediasToBeShown.push(grMedia.getUniqueValue());
            }
        }
        return "sys_idIN" + mediasToBeShown.join(",");
    },

    type: 'NowflixUtils'
};
